// Des: CLI dispatch: help, status, caps, login, run, pause, stop, resume, log
// Flo: read argv > parse ladder flags > build Ctx > call the command > exit code
// I/O: process Init (main) > u8 exit code 0-4; text on stdout
// ===================================================================
const std = @import("std"); const targ = @import("ct-ctrl-args.zig"); const ctxz = @import("ct-ctrl-ctxz.zig"); const stat = @import("ct-comm-stat.zig"); const halt = @import("ct-comm-halt.zig"); const logi = @import("ct-comm-logi.zig"); const runz = @import("ct-comm-runz.zig"); const prob = @import("ct-comm-prob.zig"); const flw = @import("ct-comm-flow.zig");
pub const HELP = "za: works Zalo Web for you at a human pace\n  za status [--json]            ready or halted, caps used\n  za caps [--json]              sends left this hour and today\n  za login                      open Zalo, scan the QR once\n  za run <job> [words] [flags]  jobs: read reply summ say send remind pin mute group forward react quote recall delete pinmsg download archive hide unread alias block sticker file poll note label quick usequick friend accept ignore reqaccept reqignore rename addmember delmember deputy leave profile cloud canary\n  za pause | stop | resume      stop all jobs at the next action, or let them go again\n  za log [--json]               last 20 activity rows\n  za probe <name>               save a redacted dump of the page (label discovery)\n  za plan '<item>' ...          make a flow, print the one approval list\n  za approve all|<ids>          approve risky items once\n  za go [--live]                run the flow by itself; waits only when Zalo needs you\n  za flow list | run <name>     named routines from flow_list\n  za watch [--live]             check the inbox at a human cadence in work sessions\n  za purge                      delete messages older than msgs_keep_days\nflags: --read (look only) · --dry (default: preview, change nothing) · --live (act) · --live --force (bulk, group, forward) · --json · --mock · --conf <file>\nexit: 0 ok · 1 fail · 2 usage · 3 finding · 4 blocked\n";
pub fn runMain(init: std.process.Init) !u8 { const allo = init.arena.allocator(); var iter = try init.minimal.args.iterateAllocator(allo); _ = iter.next(); var argv: std.ArrayList([]const u8) = .empty; while (iter.next()) |item| try argv.append(allo, item); const args = try targ.parse(allo, argv.items); var ctx = try ctxz.make(init, args); if (std.mem.eql(u8, args.cmd, "help")) { try ctxz.emit(&ctx, HELP); return 0; } if (std.mem.eql(u8, args.cmd, "status")) return stat.statRun(&ctx); if (std.mem.eql(u8, args.cmd, "caps")) return stat.capsRun(&ctx); if (std.mem.eql(u8, args.cmd, "log")) return halt.logRun(&ctx); if (std.mem.eql(u8, args.cmd, "pause")) return halt.pauseRun(&ctx, "paused by owner"); if (std.mem.eql(u8, args.cmd, "stop")) return halt.pauseRun(&ctx, "stopped by owner"); if (std.mem.eql(u8, args.cmd, "resume")) return halt.resumeRun(&ctx); if (std.mem.eql(u8, args.cmd, "purge")) return halt.purgeRun(&ctx); if (std.mem.eql(u8, args.cmd, "login")) return logi.loginRun(&ctx); if (std.mem.eql(u8, args.cmd, "run")) return runz.runRun(&ctx); if (std.mem.eql(u8, args.cmd, "probe")) return prob.probeRun(&ctx); if (std.mem.eql(u8, args.cmd, "plan")) return flw.planRun(&ctx); if (std.mem.eql(u8, args.cmd, "approve")) return flw.approveRun(&ctx); if (std.mem.eql(u8, args.cmd, "go")) return flw.goRun(&ctx); if (std.mem.eql(u8, args.cmd, "watch")) return flw.watchRun(&ctx); if (std.mem.eql(u8, args.cmd, "flow")) return flw.flowRun(&ctx); return error.BadUsage; }
